import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IHrmPlatformMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmPlatformMember";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

export async function test_api_refresh_session_transition(
  connection: api.IConnection,
): Promise<void> {
  // Prepare member identity for the test lifecycle
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(16);
  const displayName: string = RandomGenerator.name();
  const href: string = typia.random<string & tags.Format<"uri">>();
  const referrer: string = typia.random<string & tags.Format<"uri">>();
  // === Step 1: Join - Register member to get initial tokens ===
  const joinConnection: api.IConnection = { host: connection.host };
  const joined: IHrmPlatformMember.IAuthorized = await authorize_member_join(
    joinConnection,
    {
      body: {
        email,
        password,
        display_name: displayName,
        href,
        referrer,
      } satisfies IHrmPlatformMember.IJoin,
    },
  );
  typia.assert(joined);
  // Verify join response has valid identity
  TestValidator.equals(
    "join member id is valid UUID",
    typeof joined.id,
    "string",
  );
  TestValidator.equals("join email matches", joined.email, email);
  TestValidator.equals(
    "join display_name matches",
    joined.display_name,
    displayName,
  );
  TestValidator.predicate(
    "join token exists",
    joined.token.access != null && joined.token.refresh != null,
  );
  // Capture join identity for later comparison
  const joinId = joined.id;
  const joinEmail = joined.email;
  const joinDisplayName = joined.display_name;
  // === Step 2: Login - Fresh session to get new tokens ===
  const loginConnection: api.IConnection = { host: connection.host };
  const loggedIn: IHrmPlatformMember.IAuthorized = await authorize_member_login(
    loginConnection,
    {
      body: {
        email,
        password,
        href,
        referrer,
      } satisfies IHrmPlatformMember.ILogin,
    },
  );
  typia.assert(loggedIn);
  // Verify login returns IAuthorized with new tokens
  TestValidator.equals(
    "login member id is valid UUID",
    typeof loggedIn.id,
    "string",
  );
  TestValidator.equals(
    "login email matches join email",
    loggedIn.email,
    joinEmail,
  );
  TestValidator.equals(
    "login display_name matches join display_name",
    loggedIn.display_name,
    joinDisplayName,
  );
  TestValidator.equals("login id matches join id", loggedIn.id, joinId);
  TestValidator.predicate(
    "login token exists",
    loggedIn.token.access != null && loggedIn.token.refresh != null,
  );
  // Capture login refresh token for step 3
  const loginRefreshToken: string = loggedIn.token.refresh;
  // === Step 3: Refresh - Get another new token pair using login's refresh token ===
  const refreshConnection: api.IConnection = { host: connection.host };
  const refreshed: IHrmPlatformMember.IAuthorized =
    await authorize_member_refresh(refreshConnection, {
      body: {
        refresh_token: loginRefreshToken,
      } satisfies IHrmPlatformMember.IRefresh,
    });
  typia.assert(refreshed);
  // Verify refresh returns IAuthorized with new tokens
  TestValidator.equals(
    "refresh member id is valid UUID",
    typeof refreshed.id,
    "string",
  );
  TestValidator.predicate(
    "refresh token exists",
    refreshed.token.access != null && refreshed.token.refresh != null,
  );
  // === Step 4: Identity Preservation Verification ===
  // Verify that member identity is preserved across the entire refresh cycle
  TestValidator.equals(
    "refresh id matches join id (identity preserved across cycle)",
    refreshed.id,
    joinId,
  );
  TestValidator.equals(
    "refresh email matches join email (identity preserved across cycle)",
    refreshed.email,
    joinEmail,
  );
  TestValidator.equals(
    "refresh display_name matches join display_name (identity preserved across cycle)",
    refreshed.display_name,
    joinDisplayName,
  );
  // Verify identity consistency between login and refresh
  TestValidator.equals(
    "refresh id matches login id",
    refreshed.id,
    loggedIn.id,
  );
  TestValidator.equals(
    "refresh email matches login email",
    refreshed.email,
    loggedIn.email,
  );
  TestValidator.equals(
    "refresh display_name matches login display_name",
    refreshed.display_name,
    loggedIn.display_name,
  );
  // Verify tokens are different after each step (new tokens issued)
  TestValidator.notEquals(
    "refresh access token differs from login access token (new token issued)",
    refreshed.token.access,
    loggedIn.token.access,
  );
  TestValidator.notEquals(
    "refresh refresh_token differs from login refresh_token (new token issued)",
    refreshed.token.refresh,
    loginRefreshToken,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IHrmPlatformMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmPlatformMember";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

/**
 * Test the primary refresh success path: member joins to get initial tokens, then immediately uses the refresh token to obtain new tokens.
 *
 * Validates the complete session renewal workflow without re-authentication. Ensures that the refresh operation returns a new set of valid tokens while preserving the authenticated member's identity. Confirms that token properties (access/refresh tokens) are rotated (different from originals), while identity properties (id, email, display_name) remain exactly the same. Also validates that expiration metadata (expired_at, refreshable_until) is present and valid in the refreshed response.
 *
 * 1. Create a new member account using join operation to obtain initial access/refresh tokens.
 * 2. Capture the original token set and member identity details for comparison.
 * 3. Submit a refresh request using the original refresh token.
 * 4. Verify the refresh returns a new authorized response.
 * 5. Validate new tokens differ from original tokens.
 * 6. Validate member identity is preserved across the token refresh.
 * 7. Validate expiration metadata exists in the new token response.
 */
export async function test_api_refresh_identity_preservation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create isolated connection for the member actor
  const memberConnection = { host: connection.host };
  // 2. Prepare join request body with randomized data
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    href: "https://example.com",
    referrer: "https://example.com/referrer",
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies IHrmPlatformMember.IJoin;
  // 3. Join member to get initial tokens and identity
  const joined = await authorize_member_join(memberConnection, {
    body: joinBody,
  });
  typia.assert(joined);
  // 4. Prepare refresh request using the initial refresh token
  const refreshBody = {
    refresh_token: joined.token.refresh,
  } satisfies IHrmPlatformMember.IRefresh;
  // 5. Refresh tokens to get new session
  const refreshed = await authorize_member_refresh(memberConnection, {
    body: refreshBody,
  });
  typia.assert(refreshed);
  // 6. Validate tokens have been rotated (different from original)
  TestValidator.notEquals(
    "new access token differs from original",
    refreshed.token.access,
    joined.token.access,
  );
  TestValidator.notEquals(
    "new refresh token differs from original",
    refreshed.token.refresh,
    joined.token.refresh,
  );
  // 7. Validate identity is preserved
  TestValidator.equals("identity id preserved", refreshed.id, joined.id);
  TestValidator.equals(
    "identity email preserved",
    refreshed.email,
    joined.email,
  );
  TestValidator.equals(
    "identity display_name preserved",
    refreshed.display_name,
    joined.display_name,
  );
  // 8. Validate expiration metadata exists
  TestValidator.predicate(
    "token expiration metadata exists",
    !!refreshed.token.expired_at,
  );
  TestValidator.predicate(
    "refreshable until metadata exists",
    !!refreshed.token.refreshable_until,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IHrmPlatformMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmPlatformMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIHrmPlatformMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIHrmPlatformMember";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test member listing endpoint returns all registered member accounts with no filters.
 *
 * Validates the member listing happy path by sending an empty request body to PATCH /hrmPlatform/members. Verifies that the response contains valid pagination metadata and member summary records ordered by creation date.
 *
 * This is a public endpoint that does not require authentication. The test confirms the API returns properly structured paginated responses with essential member profile information while excluding sensitive authentication data.
 *
 * 1. Send PATCH request to /hrmPlatform/members with empty body (no filters).
 * 2. Validate response structure and pagination metadata (current, limit, records, pages).
 * 3. Verify pages calculation matches Math.ceil(records / limit).
 * 4. Verify data array contains member summary records with expected fields.
 * 5. If multiple results returned, verify ordering by created_at descending.
 */
export async function test_api_member_list_all_members(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare empty request body (no filters - all fields optional)
  const body = {} satisfies IHrmPlatformMember.IRequest;
  // 2. Call public member listing endpoint
  const response = await api.functional.hrmPlatform.members.index(connection, {
    body,
  });
  // 3. Assert response type (validates structure: pagination + data array)
  typia.assert(response);
  // 4. Validate pagination metadata has sensible values
  TestValidator.predicate(
    "current page is at least 1",
    response.pagination.current >= 1,
  );
  TestValidator.predicate(
    "limit is at least 1",
    response.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "records count is non-negative",
    response.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count is non-negative",
    response.pagination.pages >= 0,
  );
  // 5. Validate pages calculation: Math.ceil(records / limit), with 0 when no records
  const expectedPages =
    response.pagination.records === 0
      ? 0
      : Math.ceil(response.pagination.records / response.pagination.limit);
  TestValidator.equals(
    "pages equals ceil(records / limit)",
    response.pagination.pages,
    expectedPages,
  );
  // 6. Validate data array length matches pagination expectation (first page)
  const expectedFirstPageCount = Math.min(
    response.pagination.limit,
    response.pagination.records,
  );
  TestValidator.equals(
    "first page data length matches expected",
    response.data.length,
    expectedFirstPageCount,
  );
  // 7. If multiple results, verify ordering by created_at descending
  if (response.data.length >= 2) {
    for (let i = 0; i < response.data.length - 1; i++) {
      const currentTimestamp = new Date(response.data[i].created_at).getTime();
      const nextTimestamp = new Date(response.data[i + 1].created_at).getTime();
      TestValidator.predicate(
        `record ${i} created_at >= record ${i + 1} created_at`,
        currentTimestamp >= nextTimestamp,
      );
    }
  }
  // 8. Verify first member summary has expected properties (typia.assert already validates types)
  if (response.data.length > 0) {
    const member = response.data[0];
    TestValidator.predicate(
      "member id is valid UUID format",
      member.id.length === 36,
    );
    TestValidator.predicate("member has email", member.email.length > 0);
    TestValidator.predicate(
      "member has display name",
      member.display_name.length > 0,
    );
    TestValidator.predicate(
      "member has created_at date-time",
      member.created_at.length > 0,
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
