    "description remains unchanged",
    updatedOrg.description,
    originalDescription,
  );
  TestValidator.equals(
    "logo_uri remains unchanged",
    updatedOrg.logo_uri,
    originalLogoUri,
  );
  TestValidator.equals(
    "fiscal_start_month remains unchanged",
    updatedOrg.fiscal_start_month,
    originalFiscalStartMonth,
  );
