    async () =>
      await api.functional.hrmPlatform.member.employees.contracts.erase(
        viewerConnection,
        {
          employeeId: employee.id,
          contractId: contract.id,
        },
      ),
  );
  // 7. Verify contract remains active (deleted_at is still null)
  TestValidator.predicate(
