        name: RandomGenerator.alphabets(10),
        permissionKeys: ["project:manage", "time:manage", "time:view_all"],
      } satisfies IHrmPlatformRole.ICreate,
    },
  );
  typia.assert(role);
  // 4. Create an employee record for the authenticated member
