   * 6. Set the updated_at timestamp to reflect the modification time.
   * 7. Return the updated role record.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":roleId")
  public async update(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("roleId")
    roleId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmPlatformRole.IUpdate,
  ): Promise<IHrmPlatformRole> {
    try {
      return await putHrmPlatformMemberRolesRoleId({
        member,
        roleId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Soft-delete a custom role from the current organization. Built-in roles (Owner, Manager, Employee) cannot be deleted. Custom roles can only be deleted when no employees are currently assigned to them, preserving operational continuity.
