import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IHrmPlatformProject } from "../../../../api/structures/IHrmPlatformProject";
import { IPageIHrmPlatformProject } from "../../../../api/structures/IPageIHrmPlatformProject";
import { MemberAuth } from "../../../../decorators/MemberAuth";
import { MemberPayload } from "../../../../decorators/payload/MemberPayload";
import { deleteHrmPlatformMemberProjectsProjectId } from "../../../../providers/deleteHrmPlatformMemberProjectsProjectId";
import { getHrmPlatformMemberProjectsProjectId } from "../../../../providers/getHrmPlatformMemberProjectsProjectId";
import { patchHrmPlatformMemberProjects } from "../../../../providers/patchHrmPlatformMemberProjects";
import { patchHrmPlatformMemberProjectsProjectId } from "../../../../providers/patchHrmPlatformMemberProjectsProjectId";
import { patchHrmPlatformMemberProjectsProjectIdArchive } from "../../../../providers/patchHrmPlatformMemberProjectsProjectIdArchive";
import { postHrmPlatformMemberProjects } from "../../../../providers/postHrmPlatformMemberProjects";
import { putHrmPlatformMemberProjectsProjectId } from "../../../../providers/putHrmPlatformMemberProjectsProjectId";

@Controller("/hrmPlatform/member/projects")
export class HrmplatformMemberProjectsController {
  /**
   * Create a new project for organizing and tracking work within the organization.
   *
   * Projects serve as containers for tasks, timelogs, and team membership. Every project requires a name and color code for visual identification. Upon successful creation, the project immediately enters active status, ready for task creation and time tracking.
   *
   * @param connection
   * @param body Project creation payload requiring a unique name and hex color code within the organization. Optional description, budget, and date range fields.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Insert record into hrm_platform_projects table. Populate hrm_platform_organization_id from the authenticated member's active organization context. Set status to 'active' by default. Auto-generate id, created_at, and updated_at timestamps. Set deleted_at to null. Query database to validate no duplicate name exists within the organization. Return the complete created entity.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IHrmPlatformProject.ICreate,
  ): Promise<IHrmPlatformProject> {
    try {
      return await postHrmPlatformMemberProjects({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a filtered list of projects scoped to the authenticated member's active organization.
   *
   * This endpoint provides comprehensive project discovery and filtering capabilities with support for lifecycle status filtering (Active, Archived, Completed), full-text search on project name and description fields, and multiple sorting options. Projects are returned as summary records optimized for list displays and administrative dashboards.
   *
   * The operation enforces strict organization-level data isolation, ensuring that authenticated members can only retrieve projects within their current organization context. Results are paginated using cursor-based pagination to efficiently handle large datasets across the organization.
   *
   * @param connection
   * @param body Search and filter criteria for project listing operations. Includes pagination parameters, lifecycle status filters (Active, Archived, Completed), name and description search parameters, and sorting preferences for controlling result ordering.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_platform_projects table with organization-scoped filtering. JOIN hrm_platform_organizations to validate the authenticated member's active organization context.
   *
   * Apply request body filters including lifecycle status (Active, Archived, Completed), name substring matching (case-insensitive), and description full-text search. Support sorting by created_at, updated_at, name, status, and timeline fields.
   *
   * Return paginated results using cursor-based pagination with limit/offset parameters. Ensure empty results when the member lacks an active organization context or when no projects exist within the scope.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IHrmPlatformProject.IRequest,
  ): Promise<IPageIHrmPlatformProject.ISummary> {
    try {
      return await patchHrmPlatformMemberProjects({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieves detailed information about a specific project by its unique identifier.
   *
   * Returns the complete project entity including identification attributes (name, color_code), budget allocation, lifecycle status, timeline dates (start_date, end_date), and audit timestamps (created_at, updated_at).
   *
   * Projects are scoped to organization context - the requesting member must have access to the organization that owns this project.
   *
   * Lifecycle status indicates operational state:
   * - Active: project is operational and can receive new activities
   * - Archived: project is concluded, data preserved but no new timelogs
   * - Completed: project has reached its outcome, no new time entries allowed
   *
   * @param connection
   * @param projectId Unique UUID identifier of the project to retrieve within the current organization context.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_platform_projects table by UUID primary key matching projectId path parameter. Validate the requesting member has access to the organization context associated with this project (hrm_platform_organization_id). If the project's deleted_at field is non-null (soft deleted), return 404. If the project is not found or the member lacks permission to view the project, return 404. Do not return child collections (tasks, memberships, timelogs) - those are accessed through dedicated endpoints. Return only the project entity fields: id, hrm_platform_organization_id, name, description, color_code, budget, status, start_date, end_date, created_at, updated_at, deleted_at.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":projectId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
  ): Promise<IHrmPlatformProject> {
    try {
      return await getHrmPlatformMemberProjectsProjectId({
        member,
        projectId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update an existing project's attributes within an organization.
   *
   * Modifies project name, optional description, required hex color code for visual identification, optional budget in estimated hours, optional start and end date timeline parameters, and lifecycle status transitions. Projects can transition from Active to Archived or Completed to mark conclusion of work scopes, but Archived or Completed projects cannot be reverted back to Active to preserve historical data integrity.
   *
   * @param connection
   * @param projectId Unique identifier of the project to update within the requesting member's organization scope.
   * @param body Project attributes to update, including optional project name, optional description field, optional hex color code for list visualization, optional budget total in estimated hours, optional start and end date timeline, and optional lifecycle status with enforced transition validation.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_platform_projects table for the record matching the provided projectId UUID.
   *
   * Apply organization context validation: ensure the project's hrm_platform_organization_id matches the active organization context from the authenticated session.
   *
   * Validate request body fields:
   * - name (optional string)
   * - description (optional string)
   * - color_code (optional, required hex string format like #FF5733)
   * - budget (optional, numeric value in estimated hours)
   * - start_date (optional, DateTime)
   * - end_date (optional, DateTime)
   * - status (optional, one of 'Active'|'Archived'|'Completed')
   *
   * Enforce status transition validation:
   * - If status is being updated, validate the transition:
   *   - Active → Archived: allowed
   *   - Active → Completed: allowed
   *   - Archived → Active: DENIED (one-way transition only)
   *   - Archived → Completed: allowed
   *   - Completed → Active: DENIED (one-way transition only)
   *   - Completed → Archived: allowed
   *
   * On success, update the record with new field values and set updated_at to current server timestamp.
   * Return the fully updated IHrmPlatformProject record with all current attributes.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":projectId")
  public async update(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmPlatformProject.IUpdate,
  ): Promise<IHrmPlatformProject> {
    try {
      return await putHrmPlatformMemberProjectsProjectId({
        member,
        projectId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Mark a project as completed, transitioning it from active to terminal completed status.
   *
   * Completing a project signals that the work scope has been finished. Once completed, the project can no longer accept new timelog entries, task assignments, or timer sessions. All existing timelogs, tasks, and related data are preserved and remain accessible for historical reporting and auditing.
   *
   * Only active projects can be completed. Attempting to complete a project that is already completed or archived results in an archival status conflict error. This operation is permanent — completed projects cannot be returned to active status. Users must have project management permissions to perform this action.
   *
   * @param connection
   * @param projectId UUID of the project to complete. This uniquely identifies the project within the organization.
   * @param body Request body for completing a project. Contains optional information about the completion action.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1. Validate projectId is a valid UUID and belongs to current organization context.
   * 2. Verify project exists and is not soft-deleted (deleted_at IS NULL).
   * 3. Validate current status is 'active' — reject if status is 'completed' or 'archived' with archival status conflict error.
   * 4. Update project status to 'completed' and set updated_at to current timestamp.
   * 5. Set end_date to current datetime if end_date is currently NULL (optional — may be deferred to business rule).
   * 6. Record activity log entry for project completion event.
   * 7. Return the updated project entity with completed status.
   *
   * Error handling:
   * - 404 if project not found or deleted
   * - 409 archival status conflict if project is already completed or archived
   * - 403 if user lacks project management permissions
   *
   * Database query: UPDATE hrm_platform_projects SET status = 'completed', updated_at = NOW() WHERE id = $1 AND hrm_platform_organization_id = $2 AND deleted_at IS NULL AND status = 'active'.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch(":projectId")
  public async complete(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmPlatformProject.ICompleteRequest,
  ): Promise<IHrmPlatformProject> {
    try {
      return await patchHrmPlatformMemberProjectsProjectId({
        member,
        projectId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Deletes a project permanently when no timelogs or budget history exist.
   *
   * Permanently removes the specified project and all associated data including project memberships, tasks, and other child entities. This operation enforces strict validation to prevent deletion of projects with timelogs to maintain time tracking integrity and financial reporting continuity.
   *
   * Business constraints:
   * - Project must have zero associated timelogs
   * - Project must have no budget tracking history
   * - Requesting member must have project management permission
   * - Project must belong to the member's current organization context
   * - Projects in any status (active, archived, completed) may be deleted when constraints are satisfied
   *
   * Archived and completed projects may be deleted since they preserve history for reporting, but deletion still removes access to this preserved data.
   *
   * @param connection
   * @param projectId Project UUID identifier for the project to delete. The project ID uniquely identifies the project within the organization.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Delete hrm_platform_projects table record by UUID.
   *
   * Validation steps:
   * 1. Verify requesting member has project management permission for the organization
   * 2. Verify the project belongs to the member's current organization context
   * 3. Query hrm_platform_timelogs table for any records where hrm_platform_project_id matches projectId
   * 4. Validate timelog count is zero
   * 5. Verify no budget tracking history exists for this project
   * 6. If timelogs or budget history exist, return HTTP 409 Conflict
   * 7. If permission insufficient, return HTTP 403 Forbidden
   * 8. If project not found, return HTTP 404 Not Found
   * 9. On success, execute cascading deletion within the database transaction:
   *    - Delete from hrm_platform_project_memberships
   *    - Delete from hrm_platform_tasks
   *    - Delete from hrm_platform_timers (active timers)
   *    - Finally delete the project record itself
   * 10. Return HTTP 204 No Content on successful deletion
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":projectId")
  public async erase(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteHrmPlatformMemberProjectsProjectId({
        member,
        projectId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Archive an active project, transitioning it to the archived lifecycle state.
   *
   * This operation permanently closes the project for new activities while preserving all existing data for historical reference. Once archived, the project cannot accept new timelog entries, new tasks, or new project memberships. All existing timelogs, tasks, and membership records remain accessible.
   *
   * The project must be in active status to be archived. Attempting to archive an already archived or completed project will fail with a lifecycle status conflict error.
   *
   * @param connection
   * @param projectId UUID identifier of the project to archive (scoped to the current organization)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Find the hrm_platform_projects record by the provided projectId.
   *
   * Validate the project is in 'active' status before proceeding. If status is already 'archived' or 'completed', reject the request with a 409 Conflict response explaining that the project cannot be archived in its current lifecycle state.
   *
   * Update the project's status field from 'active' to 'archived'. Preserve all other fields unchanged.
   *
   * The operation affects downstream functionality:
   * - Timelog creation endpoints must reject new entries for archived projects
   * - Task creation endpoints must reject new tasks for archived projects
   * - Project membership additions may be restricted
   *
   * Query the project record from hrm_platform_projects where id equals projectId. Set status='archived'. Return the updated IHrmPlatformProject record.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch(":projectId/archive")
  public async archive(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
  ): Promise<IHrmPlatformProject> {
    try {
      return await patchHrmPlatformMemberProjectsProjectIdArchive({
        member,
        projectId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IHrmPlatformProjectMembership } from "../../../../../api/structures/IHrmPlatformProjectMembership";
import { IPageIHrmPlatformProjectMembership } from "../../../../../api/structures/IPageIHrmPlatformProjectMembership";
import { MemberAuth } from "../../../../../decorators/MemberAuth";
import { MemberPayload } from "../../../../../decorators/payload/MemberPayload";
import { deleteHrmPlatformMemberProjectsProjectIdMembershipsMembershipId } from "../../../../../providers/deleteHrmPlatformMemberProjectsProjectIdMembershipsMembershipId";
import { getHrmPlatformMemberProjectsProjectIdMembershipsMembershipId } from "../../../../../providers/getHrmPlatformMemberProjectsProjectIdMembershipsMembershipId";
import { patchHrmPlatformMemberProjectsProjectIdMemberships } from "../../../../../providers/patchHrmPlatformMemberProjectsProjectIdMemberships";
import { postHrmPlatformMemberProjectsProjectIdMemberships } from "../../../../../providers/postHrmPlatformMemberProjectsProjectIdMemberships";
import { putHrmPlatformMemberProjectsProjectIdMembershipsMembershipId } from "../../../../../providers/putHrmPlatformMemberProjectsProjectIdMembershipsMembershipId";

@Controller("/hrmPlatform/member/projects/:projectId/memberships")
export class HrmplatformMemberProjectsMembershipsController {
  /**
   * Create a project membership by assigning an active employee to a project with a specified capacity role.
   *
   * This operation establishes the formal association between an employee and a project, enabling authorized participation in project activities such as time tracking and task assignment. The capacity role determines the employee's permissions within the project — project leads can manage tasks while regular members can only view tasks and log time.
   *
   * The system validates that the employee is active, belongs to the same organization as the project, and is not already assigned to this project. Only users with the project:manage permission can create project memberships.
   *
   * @param connection
   * @param projectId UUID of the project to assign the employee to
   * @param body Employee assignment details including the employee UUID and the capacity role (member or project-lead) for the new project membership.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1. Validate path parameter projectId exists and belongs to current organization context
   * 2. Validate request body contains employeeId (UUID) and capacityRole (member or project-lead)
   * 3. Query hrm_platform_employees by employeeId to:
   *    a. Verify employee exists and is not soft-deleted
   *    b. Verify employee status is 'active' (reject if 'deactivated')
   *    c. Verify employee belongs to same organization as the project
   * 4. Check hrm_platform_project_memberships for existing record with same [employeeId, projectId] composite key — reject if found
   * 5. Verify current user has project:manage permission within the organization
   * 6. Insert new record into hrm_platform_project_memberships with:
   *    - id: generate UUID
   *    - hrm_platform_employee_id: from request
   *    - hrm_platform_project_id: from path parameter
   *    - capacity_role: from request (member or project-lead)
   *    - created_at: current timestamp
   *    - updated_at: current timestamp
   *    - deleted_at: null
   * 7. Return the created membership record with all fields
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmPlatformProjectMembership.ICreate,
  ): Promise<IHrmPlatformProjectMembership> {
    try {
      return await postHrmPlatformMemberProjectsProjectIdMemberships({
        member,
        projectId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Searches and lists project memberships for a specific project with advanced filtering and pagination.
   *
   * Returns all employees assigned to the project, filtered by capacity role (member or project-lead), with optional employee-level searches (name, status, department). Organization boundary enforcement ensures only authorized project members are returned.
   *
   * @param connection
   * @param projectId Project unique identifier (UUID)
   * @param body Search criteria for project memberships including employee filters, capacity role filters, and pagination settings.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_platform_project_memberships with projectId filter from path parameter. Join employees table to enable filtering on employee attributes. Filter by capacity_role, employee status, and employee_name for text searches. Exclude soft-deleted memberships (deleted_at IS NULL). Enforce organization context: verify project belongs to active organization and current user has project:manage permission. Apply cursor-based pagination with sorting by created_at.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmPlatformProjectMembership.IRequest,
  ): Promise<IPageIHrmPlatformProjectMembership.ISummary> {
    try {
      return await patchHrmPlatformMemberProjectsProjectIdMemberships({
        member,
        projectId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieves a single project membership record.
   *
   * This endpoint retrieves a particular project membership association between an employee and a project within an organization context.
   *
   * Use Cases:
   *
   * - Confirming an employee's role in a specific project
   * - Viewing detailed membership information for audit purposes
   * - Verifying membership existence before modifications
   * - Project leads can manage task assignments and permissions
   *
   * Access Control:
   *
   * - Users can view memberships if they belong to the project's organization
   * - Project members can view memberships in projects they join
   * - Manager or Owner roles have broader visibility across organization projects
   * - The record must not be soft-deleted (deleted_at IS NULL)
   *
   * @param connection
   * @param projectId Unique identifier of the project that this membership belongs to
   * @param membershipId Unique identifier of the project membership to retrieve
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
